function insightHistory(attempts){
  if(!attempts.length)return '';
  historyPage=Math.max(0,Math.min(historyPage,Math.ceil(attempts.length/20)-1));
  const rows=attempts.slice().reverse().slice(historyPage*20,(historyPage+1)*20);
  return `<div class="card mt"><div class="card-head"><h2 style="font-size:14px">Individual results</h2><span class="small muted">Open a result to inspect its setup or correct its flags.</span></div><div class="table-wrap"><table><thead><tr><th>Recorded</th><th>Case</th><th>Conditions</th><th>Solve</th><th>Inspection</th><th>Outcome</th></tr></thead><tbody>${rows.map(a=>{const c=caseMap.get(a.caseId);return `<tr><td>${new Date(a.createdAt).toLocaleString()}</td><td><button class="table-link" data-action="attempt" data-id="${esc(a.id)}">${esc(c?`${c.set} / ${c.name}`:a.caseId)}</button></td><td>${esc(a.color)} · ${a.mode==='one-look'?'one-look':'last layer'} · ${esc(none(a.preAuf))} / ${esc(none(a.postAuf))}</td><td class="result-time">${fmt(a.seconds)}s</td><td>${Number.isFinite(a.inspectionSeconds)?fmt(a.inspectionSeconds)+'s':'—'}</td><td><span class="pill ${a.dnf?'red':a.recallFail||a.assisted?'warning':''}">${a.dnf?'DNF':a.recallFail?'Recall lapse':a.assisted?'Assisted':'Clean'}</span></td></tr>`}).join('')}</tbody></table></div><div class="card-head" style="border-top:1px solid #edf0e8;border-bottom:0"><button class="button tiny" data-action="history-page" data-delta="-1" ${historyPage===0?'disabled':''}>← Newer</button><span class="small muted">${historyPage*20+1}–${Math.min((historyPage+1)*20,attempts.length)} of ${attempts.length}</span><button class="button tiny" data-action="history-page" data-delta="1" ${(historyPage+1)*20>=attempts.length?'disabled':''}>Older →</button></div></div>`;
}

const SETS=['CLL','EG1','EG2'],GROUPS=['Sune','Anti-Sune','Pi','U','L','T','H','O'];
const AUFS=['','U',"U'",'U2'],BOTTOM_AUFS=['','D',"D'",'D2'],YAWS=['','y',"y'",'y2'];
const COLOR_HEX={white:'#f7f6ed',yellow:'#e9c95a',green:'#73a484',blue:'#7698ce',red:'#d77b6a',orange:'#e9ae67'};
const allFinishes=FIRST_FACE_CASES,finishMap=new Map(allFinishes.map(f=>[f.id,f])),caseMap=new Map(CASES.map(c=>[c.id,c]));
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()??`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const pick=arr=>arr[Math.floor(Math.random()*arr.length)];
const fmt=(n,d=2)=>Number.isFinite(n)?n.toFixed(d):'—';
const pct=n=>Number.isFinite(n)?`${Math.round(n*100)}%`:'—';
const none=v=>v||'None';
const paths={train:'M3 3v18h18 M7 15l4-5 4 3 5-8',library:'M3 5h5v15H3z M10 5h5v15h-5z M17 4l4 1-2 15-4-1z',insights:'M4 20V12 M10 20V4 M16 20V8 M22 20H1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 12h14 M13 6l6 6-6 6',refresh:'M20 7v5h-5 M4 17v-5h5 M5 8a8 8 0 0 1 13-3l2 3 M19 16a8 8 0 0 1-13 3l-2-3',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',clock:'M12 8v5l3 2 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',download:'M12 3v12 M7 10l5 5 5-5 M3 16v5h18v-5',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',cube:'M12 2l9 5v10l-9 5-9-5V7z M3 7l9 5 9-5 M12 12v10',shuffle:'M3 5h3c5 0 7 14 12 14h3 M17 15l4 4-4 4 M3 19h3c5 0 7-14 12-14h3 M17 1l4 4-4 4'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.cube}"/></svg>`;
const opt=(v,label,sel)=>`<option value="${esc(v)}" ${v===sel?'selected':''}>${esc(label)}</option>`;
let lte,ltc,progress;
const fiveTrainer=()=>data?.trainer==='5x5-centres'?ltc:data?.trainer==='5x5'?lte:null;
const anyTimerActive=()=>timerActive()||lte?.active()||ltc?.active();
let data,loadError='',page='train',current=null,phase='ready',shown=false,assisted=false,inspectionStart=null;
let timerStart=0,elapsed=0,raf=0,lastResult=null,sessionId=uid(),sessionStart=Date.now();
let inspectionSeconds=null,activeTimingMode=null,activeInspectionAudio=false,spaceHeld=false;
let librarySet='CLL',libraryGroup='all',libraryQuery='',insightFilters={},insightGroup='caseId',insightSort='slow';
let historyPage=0;
let selectedDetail=null,finishQuery='',finishLength='all',finishGroup='all',toastTimer,storageBlocked=false;
const previewCache=new Map(),finishPreviewCache=new Map();
const learningSampler=createLearningSampler({random:Math.random});
const inspectionAudio=createInspectionAudio({onUnavailable:()=>toast('Inspection audio is unavailable. The timer will continue silently.')});
const timerActive=()=>phase==='inspecting'||phase==='running';
window.cornerlabTimerActive=()=>Boolean(anyTimerActive());
let reportedTimerActive=false,screenLock=null,requestingScreenLock=false;
function syncTimerState(){
  const active=Boolean(anyTimerActive());
  if(active!==reportedTimerActive){
    reportedTimerActive=active;
    window.dispatchEvent(new CustomEvent('cornerlab-timer-state',{detail:{active}}));
  }
  if(!active||document.visibilityState==='hidden'){
    if(screenLock){screenLock.release().catch(()=>{});screenLock=null;}
  }else if(!screenLock&&!requestingScreenLock&&window.navigator?.wakeLock){
    requestingScreenLock=true;
    window.navigator.wakeLock.request('screen').then(lock=>{
      requestingScreenLock=false;
      if(!anyTimerActive()||document.visibilityState==='hidden'){lock.release().catch(()=>{});return;}
      screenLock=lock;
      lock.addEventListener('release',()=>{if(screenLock===lock)screenLock=null;});
    }).catch(()=>{requestingScreenLock=false;});
  }
}
const selectedTimingMode=()=>data.settings.timingMode||(data.settings.mode==='one-look'?'inspection':'simple');
const attemptTiming=a=>a.timingMode||(Number.isFinite(a.inspectionSeconds)?'inspection':'simple');
function algorithms(c){return [...c.algorithms,...(data.preferences[c.id]?.custom||[])];}
function preferred(c){return algorithms(c).find(a=>a.id===data.preferences[c.id]?.selected)||c.algorithms[0];}
function selectedCases(){return CASES.filter(c=>data.settings.selectedCases.includes(c.id));}
function persist(){if(storageBlocked)return;saveData(data).catch(e=>{storageBlocked=true;loadError=`Your changes could not be saved: ${e.message}. Export a backup before closing.`;toast(loadError);render();});}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500);}
function caseState(c){if(!previewCache.has(c.id))previewCache.set(c.id,applyAlg(solvedState(),inverse(c.algorithms[0].alg)));return previewCache.get(c.id);}
function currentAttempts(){return data.attempts.filter(a=>a.sessionId===sessionId);}
function scopeAttempts(){const s=data.settings;return data.attempts.filter(a=>s.selectedCases.includes(a.caseId)&&a.mode===s.mode&&attemptTiming(a)===selectedTimingMode()&&(selectedTimingMode()!=='inspection'||Boolean(a.inspectionAudio)===Boolean(s.inspectionAudio))&&s.colors.includes(a.color)&&s.preAuf.includes(a.preAuf)&&s.postAuf.includes(a.postAuf)&&s.orientations.includes(a.orientation)&&(s.mode!=='one-look'||(s.finishIds.includes(a.finishCaseId)&&a.finish===finishMap.get(a.finishCaseId)?.alg&&s.bottomAuf.includes(a.bottomAuf||'')))&&a.algorithmId===preferred(caseMap.get(a.caseId)).id&&(a.algorithm===undefined||a.algorithm===preferred(caseMap.get(a.caseId)).alg));}
function resetLearning(){learningSampler.reset();if(current)current.learningBatch=null;}
function setSelected(ids,value){const set=new Set(data.settings.selectedCases);ids.forEach(id=>value?set.add(id):set.delete(id));if(JSON.stringify([...set].sort())!==JSON.stringify([...data.settings.selectedCases].sort()))resetLearning();data.settings.selectedCases=[...set];persist();}
function updateSelection(){render();}
function nextDrill(){
  if(timerActive())return;
  inspectionAudio.cancel();cancelAnimationFrame(raf);
  inspectionSeconds=null;activeTimingMode=null;activeInspectionAudio=false;
  const s=data.settings,cases=selectedCases();current=null;lastResult=null;shown=false;assisted=false;inspectionStart=null;elapsed=0;phase='ready';
  if(!cases.length){learningSampler.reset();render();return;}
  const finishes=allFinishes.filter(f=>s.finishIds.includes(f.id));
  if(s.mode==='one-look'&&!finishes.length){toast('Select at least one first-face case.');render();return;}
  if(s.strategy!=='learning')learningSampler.reset();
  const learningKey=JSON.stringify([s.mode,cases.map(c=>`${c.id}:${preferred(c).id}`).sort()]);
  const c=s.strategy==='learning'?learningSampler.next(cases,learningKey):chooseWeightedCase(cases,scopeAttempts(),s.strategy,Math.random,s.slowWindow,s.rankCount),a=preferred(c);
  const finishCase=s.mode==='one-look'?pick(finishes):null;
  const conditions={preAuf:pick(s.preAuf),postAuf:pick(s.postAuf),orientation:pick(s.orientations),color:pick(s.colors),bottomAuf:s.mode==='one-look'?pick(s.bottomAuf):'',initialAuf:s.mode==='one-look'?pick(AUFS):''};
  try {
    const drill=createDrill({caseId:c.id,alg:a.alg,...conditions,finish:finishCase?.alg||''});
    current={...drill,case:c,algorithm:a,mode:s.mode,finishCaseId:finishCase?.id||'',learningBatch:s.strategy==='learning'?learningSampler.snapshot():null};
  }catch(e){if(s.strategy==='learning')learningSampler.reset();toast(e.message);}
  render();
}
function header(){return `<header class="app-header"><div class="brand"><div class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div><div class="brand-title">Corner Lab<span style="color:#abb49f">.</span></div><div class="brand-subtitle"><select id="trainer-select" class="trainer-switch" aria-label="Trainer" ${anyTimerActive()?'disabled':''}>${opt('2x2','2 × 2 · CLL / EG',data.trainer||'2x2')}${opt('5x5','5 × 5 · Last two edges',data.trainer)}${opt('5x5-centres','5 × 5 · Last two centres',data.trainer)}</select></div></div></div><nav class="navigation" aria-label="Main navigation">${[['train','Practice'],['library','Case library'],['insights','Insights'],['settings','Settings']].map(([id,label])=>`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('')}</nav><div class="local-pill"><span class="dot"></span>${window.cornerlabNative?'ON YOUR MAC':'ON THIS DEVICE'}<span style="color:#c4cbbb"> / </span><span class="save-state">${storageBlocked?'SAVE ERROR':(data.trainer==='5x5-centres'?data.ltc.settings.record:data.trainer==='5x5'?data.lte.settings.record:data.settings.record)?'Auto-save on':'Recording off'}</span></div></header>`;}
function render(){
  $('#app').innerHTML=header()+`<main class="main page-${page}">${loadError?`<div class="error" style="margin:0 0 20px">${esc(loadError)} <button class="text-button" data-action="export">Export current data</button></div>`:''}${fiveTrainer()?fiveTrainer().content(page):page==='train'?trainPage():page==='library'?libraryPage():page==='insights'?insightsPage():settingsPage()}<footer class="footer"><span>CORNER LAB &nbsp; / &nbsp; DELIBERATE CUBE PRACTICE.</span><span>${data.trainer==='5x5-centres'?'5 × 5 · Last two centres':data.trainer==='5x5'?'5 × 5 · Last two edges':'CLL · EG1 · EG2'} &nbsp; ${window.cornerlabNative?'':'· Browser data is separate from the Mac app'}</span></footer></main>`;
  if(fiveTrainer())fiveTrainer().afterRender();else if(timerActive())tick();
  syncTimerState();
}
function metric(label,value,note,unit=''){return `<div class="metric card"><div class="metric-label">${label}</div><div class="metric-value">${value}${unit?`<small>${unit}</small>`:''}</div><div class="metric-note">${note}</div></div>`;}
function inspectionStatsHTML(attempts,scope){
  const stats=summarizeInspection(attempts);
  return `<section class="inspection-stats" aria-label="One-look inspection statistics"><div class="row between wrap"><h2>One-look inspection</h2><span class="small muted">${scope} · ${stats.count} measured inspection${stats.count===1?'':'s'}</span></div><div class="metric-grid">${metric('Average inspection',fmt(stats.average),'Arithmetic mean','s')}${metric('Under 15 seconds',pct(stats.under15Rate),'Inspection < 15s')}${metric('Under 12 seconds',pct(stats.under12Rate),'Inspection < 12s')}${metric('Under 8 seconds',pct(stats.under8Rate),'Inspection < 8s')}</div><p class="help">${stats.count?'Measured, unassisted one-look attempts; includes recall lapses and DNFs.':'Use Inspect → solve → stop in One-look mode to record inspection times.'} ${stats.count?'Untimed and assisted attempts are excluded.':''}</p></section>`;
}
function trainPage(){const stats=summarize(currentAttempts()),s=data.settings;return `<div class="page-intro"><div><div class="eyebrow" style="margin-bottom:8px">A LITTLE BETTER, EVERY SESSION</div><h1>Make every corner count.</h1><p>Build recognition. Find your rhythm. Make the next solve feel familiar.</p></div><button class="button" data-action="preset">${icon('plus')} Save practice</button></div><div class="train-layout"><section class="workspace"><div class="card timer-card"><div class="card-head"><div class="row"><span class="badge">${icon('cube')} ${[...new Set(selectedCases().map(c=>c.set))].join(' + ')||'No cases'}</span><span class="small muted">${selectedCases().length} cases selected</span></div><div class="mode-toggle" aria-label="Practice mode"><button class="${s.mode==='last-layer'?'active':''}" data-action="mode" data-mode="last-layer">Last layer</button><button class="${s.mode==='one-look'?'active':''}" data-action="mode" data-mode="one-look">One-look</button></div></div>${timingControls()}${s.mode==='one-look'?`<div class="onelook-banner">${icon('eye')} Inspect the whole solution: initial AUF → first-face case → last layer → AUF.</div>`:''}<div class="scramble-block ${phase==='done'?'scramble-completed':''}"><div class="row"><span class="eyebrow">${phase==='done'?'PREVIOUS SCRAMBLE · COMPLETED':current?'YOUR SCRAMBLE':'READY WHEN YOU ARE'}</span>${current?`<button class="text-button" data-action="copy-scramble" title="Copy scramble">Copy</button>`:''}</div><div class="scramble">${current?esc(current.scramble||'Solved cube — no moves needed'):s.selectedCases.length?'Choose your practice cases and conditions.':'Select some cases to begin.'}</div>${phase==='done'?`<p class="scramble-status" role="status">Tap timer or choose Next case to load a new scramble.</p>`:current?`<div class="small muted" style="margin-top:8px;font-size:10px">Start solved, white down · green front. Apply every move, including rotations.</div>`:''}</div><div class="timer-zone ${phase}" id="timer-zone"><button type="button" class="timer timer-touch-target" id="timer-display" data-action="timer" aria-label="${phase==='done'?'Next case':phase==='running'?'Stop timer':phase==='inspecting'?'Start solve':selectedTimingMode()==='inspection'?'Start inspection':'Start solve'}" ${!current?'disabled':''}>${timerHTML(elapsed)}</button><div class="inspection-summary">${inspectionSeconds!==null?`Inspection ${fmt(inspectionSeconds)}s · timed separately`:''}</div><div class="timer-label" id="timer-label">${timerLabel()}</div><div class="timer-actions"><button class="button primary" data-action="timer" ${!current?'disabled':''}>${timerButtonLabel()}</button>${timerActive()?'<button class="button" data-action="cancel-timer">Cancel</button>':''}<button class="button" data-action="reveal" ${!current||phase==='running'?'disabled':''}>${icon('eye')} ${shown?'Hide solution':'Reveal'}</button>${phase!=='done'?`<button class="button" data-action="next" title="Skip case (N)" ${timerActive()?'disabled':''}>${icon('refresh')}</button>`:''}</div><div class="timer-hint"><span class="key">N</span> <span class="small muted" style="font-size:9px">next</span> &nbsp; <span class="key">H</span> <span class="small muted" style="font-size:9px">reveal</span></div>${current&&s.showPreview&&phase!=='running'?`<div class="preview-cube">${cubeSVG(current.state)}<div class="eyebrow" style="font-size:7px;letter-spacing:1px">${phase==='done'?'PREVIOUS SCRAMBLED STATE':'SCRAMBLED STATE'}</div></div>`:''}</div>${phase==='ready'&&current?`<div class="manual-entry" style="margin:-7px 0 21px"><input type="number" id="manual-time" class="input" min="0.01" max="86400" step="0.01" placeholder="0.00" aria-label="Manual solve time in seconds"><button class="text-button" data-action="manual">Add time</button></div>`:''}${shown&&current?solutionHTML():''}${phase==='done'&&lastResult?`<div class="result-tools"><span class="small muted" style="font-size:10px">How did that feel?</span><label><input class="check" type="checkbox" data-result-flag="recallFail" ${lastResult.recallFail?'checked':''}> Recall lapse</label><label><input class="check" type="checkbox" data-result-flag="dnf" ${lastResult.dnf?'checked':''}> DNF</label><span class="pill ${lastResult.assisted?'warning':''}">${lastResult.assisted?'Assisted':storageBlocked?'Not saved — export backup':data.settings.record?'Saved locally':'Not recorded'}</span><button class="text-button" data-action="undo">Discard result</button></div>`:''}<div class="condition-strip"><span class="label">PRACTICING</span>${s.strategy==='learning'&&current?.learningBatch?`<span class="condition-tag">Learning batch ${current.learningBatch.batchNumber} · case ${current.learningBatch.position} of ${current.learningBatch.total}</span>`:''}<span class="condition-tag">${s.preAuf.length===4?'All':s.preAuf.map(none).join(', ')} recognition AUFs</span><span class="condition-tag">${s.postAuf.length===4?'All':s.postAuf.map(none).join(', ')} finishing AUFs</span><span class="condition-tag">${s.colors.length===1?`${s.colors[0]} first layer`:`${s.colors.length} first-layer colors`}</span><span class="condition-tag">${s.orientations.length} starting grip${s.orientations.length>1?'s':''}</span>${s.mode==='one-look'?'<span class="condition-tag">Random initial U</span>':''}</div></div><div class="metric-grid">${metric('Session solves',stats.count,'A little progress adds up')}${metric('Typical time',fmt(stats.median),'Median · clean solves','s')}${metric('Consistency',fmt(stats.mad),'MAD · lower is steadier','s')}${metric('Lapse rate',pct(stats.lapseRate),stats.count<5?'Building your baseline':'Recall, DNF + slow tail')}</div>${s.mode==='one-look'?inspectionStatsHTML(currentAttempts(),'This session'):''}${sessionHTML()}</section>${builderHTML()}</div>`;}
function timerHTML(t){const parts=(t/1000).toFixed(2).split('.');return `${parts[0]}<span class="fraction">.${parts[1]}</span>`;}
function timerLabel(){
  if(phase==='inspecting')return 'Inspecting · tap timer or press Space to solve';
  if(phase==='running')return 'Solving · tap timer or press Space to stop';
  if(phase==='done')return data.settings.record?'Result recorded. Tap timer for your next case.':'Recording off. Tap timer for your next case.';
  return selectedTimingMode()==='inspection'?'Tap timer or press <span class="key">space</span> to inspect':'Tap timer or press <span class="key">space</span> to solve';
}
function timerButtonLabel(){
  if(phase==='inspecting')return 'Start solve';
  if(phase==='running')return 'Stop timer';
  if(phase==='done')return `Next case ${icon('arrow')}`;
  return selectedTimingMode()==='inspection'?'Start inspection':'Start solve';
}
function timingControls(){
  return `<div class="timing-controls"><div class="row wrap"><span class="eyebrow">Timer</span><div class="mode-toggle" aria-label="Timing option"><button data-action="timing-mode" data-timing="simple" class="${selectedTimingMode()==='simple'?'active':''}" aria-pressed="${selectedTimingMode()==='simple'}" ${timerActive()?'disabled':''}>Start → stop</button><button data-action="timing-mode" data-timing="inspection" class="${selectedTimingMode()==='inspection'?'active':''}" aria-pressed="${selectedTimingMode()==='inspection'}" ${timerActive()?'disabled':''}>Inspect → solve → stop</button></div></div><label class="inline-check" title="One beep at 8 seconds, two at 12 seconds"><input class="check" id="inspection-audio" type="checkbox" ${data.settings.inspectionAudio?'checked':''} ${timerActive()||selectedTimingMode()!=='inspection'?'disabled':''}>8s / 12s audio cues</label></div>`;
}

function solutionHTML(){const d=current;return `<div class="solution">${cubeSVG(d.afterFinishState,{size:115})}<div class="solution-content"><h3>${esc(d.case.set)} / ${esc(d.case.name)} <span class="muted">· ${esc(d.case.group)}</span></h3>${d.setup?`<p class="mono"><span class="solution-label">Regrip</span>${esc(d.setup)}</p>`:''}${d.mode==='one-look'?`<p class="mono"><span class="solution-label">Initial AUF</span>${esc(none(d.initialAlignment))}</p>`:''}${d.finish?`<p class="small muted">First face: ${esc(finishLabel(d.finishCaseId))}</p><p class="mono"><span class="solution-label">Finish face</span>${esc(d.finish)}</p>`:''}${d.bottomSetup?`<p class="mono"><span class="solution-label">Align bottom</span>${esc(d.bottomSetup)}</p>`:''}<p class="mono"><span class="solution-label">Recognition</span>${esc(none(d.preAuf))}</p><p class="mono"><span class="solution-label">Algorithm</span>${esc(d.algorithm.alg)||'Skip — already solved'}</p><p class="mono"><span class="solution-label">Final AUF</span>${esc(none(d.postAuf))}</p><button class="text-button" data-action="case-detail" data-id="${esc(d.case.id)}" style="padding-left:0;margin-top:5px">Choose another algorithm →</button></div></div>`;}
function builderHTML(){const s=data.settings,selected=selectedCases(),activeSets=[...new Set(selected.map(c=>c.set))];return `<aside class="builder card"><div class="builder-title"><h2>Build your practice</h2>${icon('settings')}</div><div class="builder-section"><h3>Algorithm sets <button class="text-button" data-action="nav" data-page="library">Choose cases ↗</button></h3><div class="set-select">${SETS.map(set=>`<button class="set-button ${activeSets.includes(set)?'active':''}" data-action="toggle-set" data-set="${set}" aria-pressed="${activeSets.includes(set)}">${set}<small>${selected.filter(c=>c.set===set).length} / ${CASES.filter(c=>c.set===set).length}</small></button>`).join('')}</div><div class="groups">${GROUPS.map(g=>{const ids=CASES.filter(c=>activeSets.includes(c.set)&&c.group===g).map(c=>c.id),all=ids.length&&ids.every(id=>s.selectedCases.includes(id));return `<button class="chip ${all?'active':''}" data-action="toggle-group" data-group="${g}" aria-pressed="${!!all}" title="Toggle ${g} in the selected sets">${g==='Anti-Sune'?'Anti-S':g==='O'?'O / PLL':g}</button>`;}).join('')}</div><p class="help">O / PLL includes all oriented-top cases and skips.</p></div><div class="builder-section"><h3>Recognition AUF</h3>${choiceHTML('preAuf',AUFS)}<p class="help">The U adjustment before your preferred algorithm.</p><h3 style="margin-top:15px">Finishing AUF</h3>${choiceHTML('postAuf',AUFS)}</div><div class="builder-section"><h3>Starting grip</h3>${choiceHTML('orientations',YAWS)}<p class="help">Rotate the entire case around the vertical axis.</p></div><div class="builder-section"><h3>First-layer color <span class="muted small" style="font-size:9px">${s.colors.length===1?'Fixed':'Random from selection'}</span></h3><div class="color-options">${Object.keys(COLOR_HEX).map(c=>`<button class="color-choice ${s.colors.includes(c)?'active':''}" style="background:${COLOR_HEX[c]}" title="${c}" aria-label="${c} first layer" aria-pressed="${s.colors.includes(c)}" data-action="color" data-color="${c}"></button>`).join('')}</div></div>${s.mode==='one-look'?`<div class="builder-section"><h3>First-face cases <button class="text-button" data-action="finishes">Choose ↗</button></h3><div class="row wrap">${s.finishIds.length<=3?s.finishIds.map(id=>`<span class="chip">${esc(finishLabel(id))}</span>`).join(''):`<span class="chip">${s.finishIds.length} of 36 cases selected</span>`}</div><p class="help">22 families based on your First Face sheet, with your preferred U+3 insertion. Each selected variant can lead into any selected CLL / EG case.</p><h3 style="margin-top:15px">Bottom-layer rotation</h3>${choiceHTML('bottomAuf',BOTTOM_AUFS)}<p class="help">Top and bottom are rotated independently before the first-face finish is undone. Recognition AUF controls the top.</p><h3 style="margin-top:15px">Initial AUF</h3><p class="help">A random None / U / U2 / U′ is added at the end of every one-look scramble. Find the initial alignment before the first-face insertion.</p></div>`:''}<div class="builder-section"><h3>Practice focus</h3><select class="focus-select" id="focus-select" aria-label="Practice focus">${[['uniform','Balanced · equal case probability'],['learning','Learning · once per shuffled batch'],['slow','Speed · prioritize slow typical times'],['slowest','Slowest N algs'],['fastest','Fastest N algs'],['inconsistent','Recall · prioritize inconsistency'],['new','Coverage · prioritize least practised']].map(([v,l])=>opt(v,l,s.strategy)).join('')}</select>${['slowest','fastest'].includes(s.strategy)?rankCountHTML():''}${['slow','slowest','fastest'].includes(s.strategy)?speedWindowHTML():''}<p class="help">${s.strategy==='uniform'?'A fresh mix from your selected cases.':s.strategy==='learning'?'Every selected case appears once per shuffled batch, then all cases reshuffle. Skipping advances through the batch. Changing cases or preferred algorithms starts a new batch.':['slowest','fastest'].includes(s.strategy)?rankedPracticeHelp():s.strategy==='slow'?`Uses the median of the latest ${s.slowWindow??DEFAULT_SPEED_WINDOW} clean solves per case matching this practice. Fewer solves use what is available. Recall lapses, DNFs and assisted attempts are excluded.`:s.strategy==='inconsistent'?'Uses recall failures, slow-tail rate and robust spread.':'Gives less-practised cases more opportunities.'}</p></div><div class="builder-bottom"><button class="button primary" data-action="next" ${timerActive()?'disabled':''}>${icon('shuffle')} Apply & generate case</button><p>Selections apply to your next scramble.</p></div></aside>`;}
function rankCountHTML(){return `<label class="field mt"><span>Number of algorithms (N)</span><input id="rank-count" class="input" type="number" min="1" max="${MAX_RANK_COUNT}" step="1" value="${data.settings.rankCount??DEFAULT_RANK_COUNT}" ${timerActive()?'disabled':''}></label>`;}
function rankedPracticeHelp(){
  const s=data.settings,direction=s.strategy==='slowest'?'slowest':'fastest';
  return `Draws equally from up to ${s.rankCount??DEFAULT_RANK_COUNT} ${direction} selected algorithms, ranked by the median of their latest ${s.slowWindow??DEFAULT_SPEED_WINDOW} clean solves matching this practice. Rankings update after each result. Cases without matching clean times are excluded once any have times; with no times yet, all selected cases are mixed to build a baseline.`;
}
function speedWindowHTML(){return `<label class="field mt"><span>${['slowest','fastest'].includes(data.settings.strategy)?'Recent clean solves per algorithm':'Clean solves per case (N)'}</span><input id="speed-window" class="input" type="number" min="1" max="${MAX_SPEED_WINDOW}" step="1" value="${data.settings.slowWindow??DEFAULT_SPEED_WINDOW}" ${timerActive()?'disabled':''}></label>`;}
function choiceHTML(key,values){return `<div class="choice-row">${values.map(v=>`<button class="choice ${data.settings[key].includes(v)?'active':''}" data-action="condition" data-key="${key}" data-value="${esc(v)}" aria-pressed="${data.settings[key].includes(v)}">${v||'None'}</button>`).join('')}</div>`;}
function sessionHTML(){const attempts=currentAttempts().slice().reverse();return `<div class="session-card card"><div class="card-head"><div class="row"><h2>Session history</h2><span class="pill">${attempts.length}</span></div><button class="text-button" data-action="new-session">New session</button></div>${attempts.length?`<div class="table-wrap"><table><thead><tr><th>Case</th><th>Conditions</th><th>Solve</th><th>Inspection</th><th>Result</th><th></th></tr></thead><tbody>${attempts.slice(0,8).map(a=>{const c=caseMap.get(a.caseId);return `<tr><td><button class="table-link" data-action="attempt" data-id="${esc(a.id)}">${esc(c?`${c.set} / ${c.name}`:a.caseId)}</button></td><td><span class="recent-label">${esc(a.color)} · ${a.mode==='one-look'?'one-look':'last layer'} · ${esc(none(a.preAuf))} / ${esc(none(a.postAuf))}</span></td><td class="result-time">${fmt(a.seconds)}s</td><td>${Number.isFinite(a.inspectionSeconds)?fmt(a.inspectionSeconds)+'s':'—'}</td><td><span class="pill ${a.dnf?'red':a.recallFail||a.assisted?'warning':''}">${a.dnf?'DNF':a.recallFail?'Recall lapse':a.assisted?'Assisted':'Clean'}</span></td><td><button class="text-button" data-action="attempt" data-id="${esc(a.id)}">↗</button></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty">${icon('clock')}<br>Your practice starts here.<br>Complete a solve and watch your progress take shape.</div>`}</div>`;}
function libraryCases(){return CASES.filter(c=>c.set===librarySet&&(libraryGroup==='all'||c.group===libraryGroup)&&`${c.name} ${c.title||''} ${c.group} ${c.set} ${c.id}`.toLowerCase().includes(libraryQuery.toLowerCase()));}
function libraryPage(){const cases=libraryCases();return `<div class="page-intro"><div><div class="eyebrow" style="margin-bottom:8px">A HOME FOR EVERY CASE</div><h1>Your algorithm library.</h1><p>Choose your cases and make each algorithm your own. ${CASES.length} complete cases, including O / PLL.</p></div><button class="button primary" data-action="start-selection">Practice ${data.settings.selectedCases.length} cases ${icon('arrow')}</button></div><div class="card library-toolbar"><div class="row wrap"><div class="mode-toggle">${SETS.map(s=>`<button class="${librarySet===s?'active':''}" data-action="library-set" data-set="${s}">${s} <span class="muted">${CASES.filter(c=>c.set===s).length}</span></button>`).join('')}</div><select id="library-group" style="width:135px" aria-label="Pattern group">${opt('all','All patterns',libraryGroup)}${GROUPS.map(g=>opt(g,g==='O'?'O / PLL':g,libraryGroup)).join('')}</select></div><div class="row"><button class="text-button" data-action="library-select" data-value="all">Select shown</button><button class="text-button" data-action="library-select" data-value="none">Clear shown</button><div class="search-field">${icon('search')}<input class="input" id="library-search" value="${esc(libraryQuery)}" placeholder="Find a case…" aria-label="Search cases"></div></div></div><div id="library-results">${libraryResults(cases)}</div>`;}
function libraryResults(cases=libraryCases()){return GROUPS.filter(g=>cases.some(c=>c.group===g)).map(g=>`<section class="library-section"><div class="section-heading"><h2>${g==='O'?'O / PLL · oriented top':g} <span class="small muted">&nbsp; ${cases.filter(c=>c.group===g).length} cases</span></h2><button class="text-button" data-action="library-pattern" data-group="${g}">Toggle pattern</button></div><div class="case-grid">${cases.filter(c=>c.group===g).map(c=>{const stats=summarize(data.attempts.filter(a=>a.caseId===c.id&&a.algorithmId===preferred(c).id));return `<article class="case-card card ${data.settings.selectedCases.includes(c.id)?'selected':''}" data-action="case-detail" data-id="${esc(c.id)}" tabindex="0" role="button" aria-label="Edit ${esc(c.set+' '+c.name)} algorithms"><input type="checkbox" class="case-check check" data-case-check="${esc(c.id)}" aria-label="Select ${esc(c.set+' '+c.name)} for practice" ${data.settings.selectedCases.includes(c.id)?'checked':''}>${topSVG(caseState(c))}<div><div class="case-name">${esc(c.name)}</div>${c.group==='O'?`<div class="case-meta" style="margin:0 0 7px;line-height:1.5">${esc(c.title)}</div>`:''}<span class="pill">${c.set}</span><div class="case-meta">${algorithms(c).length} algorithm${algorithms(c).length===1?'':'s'} · ${stats.count?fmt(stats.median)+'s':'Not practised'}</div></div></article>`;}).join('')}</div></section>`).join('')||'<div class="card empty">No cases match your search.</div>';}
function filteredInsights(){const f={...insightFilters};const selectionOnly=f.selectionOnly;delete f.selectionOnly;if(f.inspectionAudio==='on')f.inspectionAudio=true;else if(f.inspectionAudio==='off')f.inspectionAudio=false;for(const k of ['preAuf','postAuf','bottomAuf','initialAuf','orientation','finishCaseId'])if(f[k]==='none')f[k]=[''];const attempts=data.attempts.map(a=>({...a,timingMode:attemptTiming(a),inspectionAudio:Boolean(a.inspectionAudio),bottomAuf:a.bottomAuf||'',initialAuf:a.initialAuf||'',finishCaseId:a.finishCaseId||''}));return filterAttempts(selectionOnly?attempts.filter(a=>data.settings.selectedCases.includes(a.caseId)):attempts,f);}
function filterSelect(key,label,options){return `<label class="field"><span>${label}</span><select data-insight-filter="${key}">${opt('all','All',insightFilters[key]||'all')}${options.map(([v,l])=>opt(v,l,insightFilters[key])).join('')}</select></label>`;}
function insightsPage(){const attempts=filteredInsights(),stats=summarize(attempts);return `<div class="page-intro"><div><div class="eyebrow" style="margin-bottom:8px">KNOW WHAT TO PRACTISE NEXT</div><h1>Speed is only half the story.</h1><p>Separate steady execution from uncertain recall. Every result keeps its exact training conditions.</p></div><button class="button" data-action="export-csv">${icon('download')} Export results</button></div>${progress.content({trainer:'2x2'})}<div class="card insights-filters">${filterSelect('set','Algorithm set',SETS.map(s=>[s,s]))}${filterSelect('group','Pattern',GROUPS.map(g=>[g,g==='O'?'O / PLL':g]))}${filterSelect('caseId','Case',CASES.filter(c=>!insightFilters.set||insightFilters.set==='all'||c.set===insightFilters.set).map(c=>[c.id,`${c.set} / ${c.name}`]))}${filterSelect('mode','Practice mode',[['last-layer','Last layer'],['one-look','One-look']])}${filterSelect('timingMode','Timing option',[['simple','Start → stop'],['inspection','Inspect → solve → stop']])}${filterSelect('inspectionAudio','Inspection cues',[['on','8s / 12s'],['off','Off']])}${filterSelect('color','First-layer color',Object.keys(COLOR_HEX).map(c=>[c,c]))}${filterSelect('preAuf','Recognition AUF',AUFS.map(v=>[v||'none',none(v)]))}${filterSelect('postAuf','Finishing AUF',AUFS.map(v=>[v||'none',none(v)]))}${filterSelect('initialAuf','Initial AUF (scramble)',AUFS.map(v=>[v||'none',none(v)]))}${filterSelect('bottomAuf','Bottom rotation',BOTTOM_AUFS.map(v=>[v||'none',none(v)]))}${filterSelect('finishCaseId','First-face case',allFinishes.map(f=>[f.id,finishLabel(f.id)]))}${filterSelect('orientation','Starting grip',YAWS.map(v=>[v||'none',none(v)]))}${filterSelect('algorithmId','Algorithm version',[...new Map(data.attempts.filter(a=>a.algorithmId).map(a=>[a.algorithmId,[a.algorithmId,`${caseMap.get(a.caseId)?.name||a.caseId} · ${a.algorithm}`]])).values()])}${filterSelect('finish','First-layer finish',[...new Set(data.attempts.map(a=>a.finish).filter(Boolean))].map(f=>[f,f]))}${filterSelect('sessionId','Session',[...new Map(data.attempts.filter(a=>a.sessionId).map(a=>[a.sessionId,[a.sessionId,new Date(a.createdAt).toLocaleDateString()+' '+a.sessionId.slice(0,5)]] )).values()])}<label class="field"><span>Since date</span><input class="input" type="date" data-insight-filter="since" value="${esc(insightFilters.since||'')}"></label><label class="inline-check"><input class="check" type="checkbox" id="insight-selection" ${insightFilters.selectionOnly?'checked':''}>Only selected practice cases</label><button class="text-button" data-action="clear-filters">Clear filters</button></div><div class="metric-grid insights-metrics">${metric('Recorded solves',stats.count,`${stats.successCount} clean · ${stats.assistedCount} assisted`)}${metric('Typical speed',fmt(stats.median),'Median of clean, unassisted solves','s')}${metric('Robust spread',fmt(stats.mad),'Median absolute deviation','s')}${metric('Slow tail · P90',fmt(stats.p90),`${pct(stats.lapseRate)} lapse rate`,'s')}</div>${inspectionStatsHTML(attempts,'Matching results')}${chartHTML(attempts)}<div class="insight-explainer"><div><h3>Slow but steady?</h3><p>A high clean median and low MAD suggest execution speed is the opportunity. “Speed” focus gives these cases more practice.</p></div><div><h3>Fast, until you forget?</h3><p>Recall flags, DNFs and a long slow tail suggest inconsistent memory. “Recall” focus uses lapse rate and relative spread. Automatic tail detection needs 5 clean solves per group.</p></div></div><div class="card"><div class="card-head"><h2 style="font-size:14px">Where to focus</h2><div class="row"><select id="insight-group" style="width:160px" aria-label="Group insights">${[['caseId','By case'],['algorithmId','By algorithm version'],['group','By pattern'],['set','By algorithm set'],['preAuf','By recognition AUF'],['postAuf','By final AUF'],['orientation','By starting grip'],['color','By color'],['finishCaseId','By first-face case'],['bottomAuf','By bottom rotation'],['initialAuf','By initial AUF'],['finish','By finish moves'],['mode','By practice mode'],['timingMode','By timing option']].map(([v,l])=>opt(v,l,insightGroup)).join('')}</select><select id="insight-sort" style="width:145px" aria-label="Sort insights">${[['slow','Slowest typical'],['inconsistent','Most inconsistent'],['new','Least practised']].map(([v,l])=>opt(v,l,insightSort)).join('')}</select></div></div><div class="summary-window"><label class="field"><span>Recent solves per algorithm</span><input class="input" id="insights-window" type="number" min="1" max="${MAX_INSIGHTS_WINDOW}" step="1" value="${data.settings.insightsWindow??DEFAULT_INSIGHTS_WINDOW}" ${timerActive()?'disabled':''}></label><p class="help">This table uses the latest ${data.settings.insightsWindow??DEFAULT_INSIGHTS_WINDOW} matching results per algorithm version, including flagged outcomes. Average and median use clean solves. With fewer results, all available ones are used. Totals, charts, individual history, exports and resets keep the full filtered history.</p></div>${insightTable(attempts)}</div>${insightHistory(attempts)}<div class="row between mt"><span class="small muted">${attempts.length} results match these filters. Original times are always retained.</span><button class="button danger" data-action="reset-filtered">Reset matching results…</button></div>`;}
function chartHTML(attempts){const rows=attempts.filter(a=>a.seconds>0).slice(-60);if(!rows.length)return `<div class="card empty" style="padding:40px">${icon('insights')}<br>Your practice has a story to tell.<br>Record a few solves to see your speed and consistency here.</div>`;const max=Math.max(...rows.map(a=>a.seconds),1),w=900,h=135;return `<div class="card chart-card"><div class="row between"><h2 style="font-size:13px">Your recent rhythm</h2><span class="small muted" style="font-size:10px">Last ${rows.length} results · green clean · gold lapse / assisted · red DNF</span></div><svg class="chart" viewBox="0 0 950 165" role="img" aria-label="Recent solve times"><line x1="35" y1="145" x2="940" y2="145" stroke="#e6ecde"/><line x1="35" y1="78" x2="940" y2="78" stroke="#eef2e8" stroke-dasharray="4 5"/><text x="0" y="16" fill="#9faa90" font-size="10">${fmt(max,1)}s</text><text x="9" y="148" fill="#9faa90" font-size="10">0s</text>${rows.map((a,i)=>{const x=42+i*(w/Math.max(rows.length,2)),y=145-(a.seconds/max)*h;return `<line x1="${x}" x2="${x}" y1="145" y2="${y}" stroke="${a.dnf?'#db8a76':a.recallFail||a.assisted?'#ddbf79':'#a3b797'}" stroke-width="${Math.min(10,w/rows.length/2)}" stroke-linecap="round"/><circle cx="${x}" cy="${y}" r="3" fill="${a.dnf?'#c96e56':a.recallFail||a.assisted?'#c5a353':'#66895a'}"><title>${esc(a.seconds+'s · '+(caseMap.get(a.caseId)?.name||a.caseId))}</title></circle>`;}).join('')}</svg><div class="chart-labels"><span>${new Date(rows[0].createdAt).toLocaleString()}</span><span>${new Date(rows.at(-1).createdAt).toLocaleString()}</span></div></div>`;}
function insightTable(attempts){const recent=recentAlgorithmAttempts(attempts,data.settings.insightsWindow??DEFAULT_INSIGHTS_WINDOW);const groups=new Map();for(const a of recent){const key=insightGroup==='algorithmId'?JSON.stringify([a.caseId??null,a.algorithmId??null,a.algorithm??null]):a[insightGroup]??'';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(a);}const rows=[...groups].map(([key,arr])=>({key,arr,s:summarize(arr)}));rows.sort((a,b)=>insightSort==='slow'?(b.s.median??-1)-(a.s.median??-1):insightSort==='new'?a.s.count-b.s.count:(b.s.lapseRate||0)-(a.s.lapseRate||0)||(b.s.relativeSpread||0)-(a.s.relativeSpread||0));if(!rows.length)return '<div class="empty">No results in this selection yet.</div>';return `<div class="table-wrap"><table><thead><tr><th>${insightGroup==='caseId'?'Case':'Group'}</th><th>Recent solves</th><th>Clean average</th><th>Clean median</th><th>MAD</th><th>P90</th><th>Lapses</th><th>Readout</th></tr></thead><tbody>${rows.map(({key,arr,s})=>{let label=key||'None';if(insightGroup==='caseId'){const c=caseMap.get(key);label=c?`${c.set} / ${c.name}`:key;}if(insightGroup==='finishCaseId')label=finishLabel(key)||'Legacy / no first-face case';if(insightGroup==='timingMode')label=key==='inspection'?'Inspect → solve → stop':'Start → stop';if(insightGroup==='algorithmId')label=`${caseMap.get(arr[0].caseId)?.name||''} · ${arr[0].algorithm}`;return `<tr><td>${insightGroup==='caseId'?`<button class="table-link" data-action="case-detail" data-id="${esc(key)}">${esc(label)}</button>`:esc(label)}</td><td>${s.count}</td><td>${fmt(s.average)}s</td><td><strong>${fmt(s.median)}s</strong></td><td>${fmt(s.mad)}s</td><td>${fmt(s.p90)}s</td><td>${pct(s.lapseRate)} <span class="muted">(${s.lapseCount})</span></td><td><span class="pill ${s.sufficient&&s.lapseRate>.15?'warning':''}">${!s.sufficient?'Building baseline':s.lapseRate>.15?'Recall needs work':s.relativeSpread>.2?'Variable pace':'Steady'}</span></td></tr>`;}).join('')}</tbody></table></div>`;}
function settingsPage(){return `<div class="page-intro"><div><div class="eyebrow" style="margin-bottom:8px">BUILT AROUND YOUR PRACTICE</div><h1>Make yourself at home.</h1><p>Your algorithms, your practice conditions, your data. Everything stays on this device.</p></div><span class="badge">Version 1.6.0</span></div><div class="settings-grid"><section class="card settings-card"><h2>Recording & display</h2><p>Keep a full training history, or turn recording off for casual practice.</p><div class="switch-row"><label for="record-toggle">Store solve statistics<small>Includes case, exact algorithm, AUFs, grip, color, finish and outcome.</small></label><input class="check" id="record-toggle" type="checkbox" ${data.settings.record?'checked':''}></div><div class="switch-row"><label for="preview-toggle">Show scrambled cube preview<small>Hidden while the timer runs. Case names remain hidden until reveal.</small></label><input class="check" id="preview-toggle" type="checkbox" ${data.settings.showPreview?'checked':''}></div>${timingControls()}<div class="notice">Tap the large timer or press Space to advance it. Cancel stops timing without saving a result. Start → stop takes two presses; Inspect → solve → stop takes three. Optional inspection cues sound once at 8s and twice at 12s. N: next case. H: reveal. Escape: cancel inspection or solving. Revealing before or during inspection marks the result assisted.</div></section><section class="card settings-card"><h2>Your data, safely kept</h2><p>${window.cornerlabNative?'The app saves to Application Support/Corner Lab/data.json, with a previous-file backup.':'Your history is saved on this device and works offline. Clearing website data or removing the Home Screen app can remove this history.'} Export backups to move or protect your history.</p><div class="row wrap"><button class="button primary" data-action="export">${icon('download')} Export full backup</button><button class="button" data-action="import">Import backup…</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p style="margin-top:20px;margin-bottom:0">${data.attempts.length} 2×2 results · ${data.lte.attempts.length} 5×5 edges results · ${data.ltc.attempts.length} 5×5 centres results · ${Object.values(data.preferences).reduce((n,p)=>n+(p.custom?.length||0),0)} personal algorithms · ${data.presets.length} saved practices</p><div class="row"><button class="text-button" data-action="nav" data-page="insights">Filter and reset specific results →</button></div></section><section class="card settings-card"><h2>Saved practices</h2><p>Keep separate selections for new algorithms, AUF drills and one-look sessions.</p>${data.presets.length?data.presets.map(p=>`<div class="row between" style="border-top:1px solid #edf1e6;padding-top:12px"><div><strong style="font-size:12px">${esc(p.name)}</strong><div class="small muted" style="font-size:10px;margin-top:4px">${p.settings.selectedCases.length} cases · ${p.settings.mode==='one-look'?'one-look':'last layer'}</div></div><div class="row"><button class="button tiny" data-action="load-preset" data-id="${esc(p.id)}">Load</button><button class="text-button" data-action="delete-preset" data-id="${esc(p.id)}">Delete</button></div></div>`).join(''):'<div class="empty" style="padding:12px">Save your first practice from the Practice screen.</div>'}<button class="button mt" data-action="preset">${icon('plus')} Save current practice</button></section><section class="card settings-card"><h2>How practice is constructed</h2><p>Every scramble is generated from the inverse of a complete, verified solution. It includes your first-layer finish, recognition AUF, chosen algorithm and final AUF. Starting grip is a whole-cube y rotation, with its regrip shown in the reveal.</p><p>One-look uses the 22 families and 36 named variants based on your 2x2 First Face sheet, with your preferred R U′ R′ insertion for U+3. For every selected CLL / EG case, top and bottom are rotated independently before applying the inverse first-face finish. A random initial U turn (None, U, U2 or U′) is added at the end of the scramble. The reveal shows its inverse before the first-face insertion, plus any bottom alignment afterward. Color selection rotates the solved color scheme before scrambling.</p><p>Times are self-reported with the touch timer, keyboard or manual entry; the app does not connect to a smart cube or infer recall failures.</p></section><section class="card settings-card"><h2>Understanding the numbers</h2><p><strong>Median</strong> tracks typical clean execution; <strong>MAD</strong> is the median absolute deviation from that median. Recall failures, DNFs and assisted attempts are excluded from both. <strong>P90</strong> measures the slower end of all unassisted times.</p><p>A lapse is an explicit recall failure / DNF or an unusually slow clean solve above the largest of 1.75 × median, median + 3 × scaled MAD, and median + 2 seconds. Tail detection starts after 5 clean results. A slow time is a signal to review, not proof of a memory failure.</p><p>Focus weighting uses your currently selected algorithms, mode and condition ranges. Speed and the Slowest / Fastest N modes use the median of recent clean solves per case; adjust the clean-solve window under Practice focus (default 20). Ranked modes draw equally from up to N selected cases with matching times. The Insights table has its own recent-results window (default 20 per algorithm version). Filter narrowly in Insights to compare like with like.</p><p><strong>One-look inspection</strong> shows the average measured time and percentages strictly under 15, 12 and 8 seconds. It includes unassisted timed inspections, including recall lapses and DNFs, and follows your Insights filters.</p></section><section class="card settings-card"><h2>Sources & acknowledgements</h2><p>Algorithm choices are adapted from Malte Ihlefeld’s Alg-Trainers, with additional verified cases and alternatives from J Perm. First-face cases are transcribed from your 2x2 FF.pdf sheet. Source case names are retained; different sites may number cases differently.</p><div class="row wrap"><a class="button" href="https://github.com/mihlefeld/Alg-Trainers" target="_blank" rel="noreferrer">Alg-Trainers ↗</a><a class="button" href="https://jperm.net/algs/2x2/cll" target="_blank" rel="noreferrer">J Perm CLL ↗</a></div><p style="margin-top:20px">Corner Lab is free software under GPL v3. See LICENSE and NOTICE in the source distribution for credits and terms. Provided without warranty.</p></section></div>`;}

function modal(title,body,foot=''){ $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</section></div>`;setTimeout(()=>$('.modal input:not([type=radio]):not([type=checkbox]),.modal button')?.focus(),0);}
function closeModal(){selectedDetail=null;$('#modal-root').innerHTML='';}
function showCase(id){const c=caseMap.get(id);if(!c)return;selectedDetail=id;const chosen=preferred(c);modal(`${c.set} / ${c.name}`,`<div class="case-detail-top">${cubeSVG(caseState(c),{size:140})}<div><div class="eyebrow">${esc(c.group==='O'?'Oriented top / PLL':c.group)}</div><h2 style="margin:8px 0">Choose your preferred algorithm.</h2>${c.title?`<p style="color:#526d44;margin-bottom:7px">${esc(c.title)}</p>`:''}<p>All choices solve this exact reference case. Starting adjustments are included.<br>Personal algorithms are checked on the cube before they can be saved.</p><p class="help">${c.set==='CLL'?'Reference: solved first layer on the bottom.':c.set==='EG1'?'Reference: first-layer bar at the back, face on the bottom.':'Reference: diagonal swap below, face on the bottom.'}</p></div></div><div id="alg-choices">${algorithms(c).map(a=>`<div class="alg-row ${a.id===chosen.id?'active':''}"><input type="radio" name="preferred-alg" value="${esc(a.id)}" aria-label="Use ${esc(a.alg||'Skip')}" ${a.id===chosen.id?'checked':''}><label data-action="choose-alg" data-id="${esc(a.id)}"><div class="alg mono">${esc(a.alg)||'Skip — no algorithm needed'}</div><div class="source">${a.url?`<a href="${esc(a.url)}" target="_blank" rel="noreferrer">${esc(a.source||'Source')} ↗</a>`:esc(a.source||'Personal algorithm')} ${a.id===chosen.id?'· Preferred':''}</div></label><button class="text-button" data-action="copy-alg" data-id="${esc(a.id)}">Edit copy</button>${data.preferences[c.id]?.custom?.some(custom=>custom.id===a.id)?`<button class="text-button" data-action="remove-alg" data-id="${esc(a.id)}">Remove</button>`:''}</div>`).join('')}</div><div style="border-top:1px solid #e8eedd;margin-top:24px;padding-top:20px"><h3>Add your own</h3><p class="help" style="margin-bottom:11px">Use R U R′, R2, x/y/z, or grouped notation. Include any starting U or y setup. A required final AUF is added automatically.</p><textarea id="custom-alg" placeholder="Your preferred algorithm…" aria-label="Custom algorithm"></textarea><div id="custom-alg-error"></div><button class="button primary mt" data-action="save-alg">Validate & use algorithm</button></div>`,`<button class="button" data-action="practice-case" data-id="${esc(c.id)}">Practise only this case</button><button class="button primary" data-action="close-modal">Done</button>`);}
function finishLabel(id){const f=finishMap.get(id);return f?`${f.group} / ${f.name}`:id||'';}
function finishPreview(f){if(!finishPreviewCache.has(f.id))finishPreviewCache.set(f.id,firstFaceSVG(applyAlg(solvedState(),inverse(f.alg))));return finishPreviewCache.get(f.id);}
function showFinishes(){modal('Choose first-face cases',`<p class="small muted">22 families · 36 named variants from your <strong>2x2 First Face</strong> sheet. Select a family or individual variants. Every selected case can lead into any selected CLL, EG1 or EG2 case.</p><div class="finish-toolbar mt"><input class="input" id="finish-search" placeholder="Search case or moves, e.g. U+3" value="${esc(finishQuery)}" aria-label="Search first-face cases"><select id="finish-group" aria-label="First-face group">${opt('all','All groups',finishGroup)}${FIRST_FACE_GROUPS.map(g=>opt(g,g,finishGroup)).join('')}</select><select id="finish-length" aria-label="Finish length">${opt('all','All lengths',finishLength)}${[1,3,4,5].map(n=>opt(String(n),`${n} move${n>1?'s':''}`,finishLength)).join('')}</select></div><div class="row between wrap"><div><button class="text-button" data-action="finish-select" data-value="all">Select all matches</button><button class="text-button" data-action="finish-select" data-value="none">Clear matches</button></div><button class="text-button" data-action="finish-defaults">R U R′ + R U′ R′ only</button></div><div id="finish-results">${finishResults()}</div><p class="help mt">Yellow marks the four stickers of the first face; other colors are hidden. Face labels fix the grip. U+3 uses your preferred R U′ R′ insertion; the other algorithms are the sheet’s primary choices. Half turns count as one move.</p>`,`<button class="button primary" data-action="close-modal">Use selection</button>`);}
function matchingFinishes(){const q=finishQuery.replace(/[’′]/g,"'").trim().toLowerCase().replace(/\s+/g,' ');return allFinishes.filter(f=>(finishLength==='all'||f.length===Number(finishLength))&&(finishGroup==='all'||f.group===finishGroup)&&`${f.group} ${f.name} ${f.alg}`.toLowerCase().includes(q));}
function finishResults(){
  const matches=matchingFinishes(),ids=new Set(matches.map(f=>f.id));
  return `<div class="row between mt"><span class="selection-summary">${data.settings.finishIds.length} selected · ${matches.length} match${matches.length===1?'':'es'}</span><span class="small muted">22 families / 36 variants</span></div><div class="first-face-groups">${FIRST_FACE_GROUPS.map(group=>{
    const families=FIRST_FACE_FAMILIES.filter(f=>f.group===group&&f.caseIds.some(id=>ids.has(id)));
    if(!families.length)return '';
    return `<section class="first-face-section"><h3>${group}<span>${families.length} ${families.length===1?'family':'families'}</span></h3><div class="first-face-grid">${families.map(family=>{
      const variants=family.caseIds.filter(id=>ids.has(id)).map(id=>finishMap.get(id));
      const all=variants.every(f=>data.settings.finishIds.includes(f.id));
      return `<div class="first-face-family"><div class="first-face-family-head"><span>${esc(family.name)}</span><button class="text-button" data-action="finish-family" data-family="${family.id}" aria-label="${all?'Clear':'Select'} ${esc(family.name)} family">${all?'Clear':'Select'} family</button></div>${variants.map(f=>`<label class="first-face-case"><input type="checkbox" class="check" data-finish="${f.id}" aria-label="${esc(f.group+' / '+f.name+' · '+f.alg)}" ${data.settings.finishIds.includes(f.id)?'checked':''}>${finishPreview(f)}<span class="first-face-info"><strong>${esc(f.name)}</strong><span class="mono">${esc(f.alg)}</span><small>${f.length} move${f.length>1?'s':''}${f.breaksBar?' · breaks bar':''}${f.userAdapted?' · your preferred insertion':''}</small></span></label>`).join('')}</div>`;
    }).join('')}</div></section>`;
  }).join('')||'<div class="empty">No matching first-face cases.</div>'}</div>`;
}
function showAttempt(id){const a=data.attempts.find(a=>a.id===id);if(!a)return;const c=caseMap.get(a.caseId);modal(`${c?.set||a.set} / ${c?.name||a.caseId} · ${fmt(a.seconds)}s`,`<dl class="history-detail">${[['Recorded',new Date(a.createdAt).toLocaleString()],['Practice mode',a.mode],['First-layer color',a.color],['Starting grip',none(a.orientation)],['Initial AUF (scramble)',none(a.initialAuf)],['Recognition AUF',none(a.preAuf)],['Finishing AUF',none(a.postAuf)],['First-face case',finishLabel(a.finishCaseId)||'Legacy / no first-face case'],['Bottom rotation',none(a.bottomAuf)],['First-face finish',none(a.finish)],['Timing',attemptTiming(a)==='inspection'?'Inspect → solve → stop':'Start → stop'],['Inspection',Number.isFinite(a.inspectionSeconds)?`${fmt(a.inspectionSeconds)}s`:'Not separately timed'],['Inspection cues',a.inspectionAudio?'8s / 12s':'Off'],['Algorithm',a.algorithm||'Skip'],['Scramble',a.scramble],['Full solution',a.solution]].map(([k,v])=>`<div class="${['Algorithm','Scramble','Full solution'].includes(k)?'full':''}"><dt>${k}</dt><dd class="${['Algorithm','Scramble','Full solution','First-face finish'].includes(k)?'mono':''}">${esc(v)}</dd></div>`).join('')}</dl><div class="row wrap mt">${['recallFail','dnf','assisted'].map(f=>`<label class="inline-check"><input type="checkbox" class="check" data-attempt-flag="${f}" data-id="${esc(id)}" ${a[f]?'checked':''}>${f==='recallFail'?'Recall lapse':f==='dnf'?'DNF':'Assisted'}</label>`).join('')}</div>`,`<button class="button danger" data-action="delete-attempt" data-id="${esc(id)}">Delete this result</button><button class="button primary" data-action="close-modal">Done</button>`);}

function startInspection(){
  if(!current||phase!=='ready')return;
  activeTimingMode='inspection';activeInspectionAudio=Boolean(data.settings.inspectionAudio);
  inspectionStart=performance.now();inspectionSeconds=null;elapsed=0;phase='inspecting';
  if(activeInspectionAudio)inspectionAudio.start();
  render();
}
function startTimer(){
  if(!current||!['ready','inspecting'].includes(phase))return;
  const now=performance.now();
  if(phase==='inspecting')inspectionSeconds=Math.max(0,(now-inspectionStart)/1000);
  else {activeTimingMode='simple';activeInspectionAudio=false;inspectionStart=null;inspectionSeconds=null;}
  inspectionAudio.cancel();elapsed=0;timerStart=now;phase='running';render();
}
function tick(){
  cancelAnimationFrame(raf);if(!timerActive())return;
  elapsed=Math.max(0,performance.now()-(phase==='inspecting'?inspectionStart:timerStart));
  const node=$('#timer-display');if(node)node.innerHTML=timerHTML(elapsed);
  raf=requestAnimationFrame(tick);
}
function finishTimer(seconds=null){
  if(!current||(seconds===null&&phase!=='running'))return;
  inspectionAudio.cancel();cancelAnimationFrame(raf);
  elapsed=seconds!==null?seconds*1000:performance.now()-timerStart;phase='done';
  lastResult={id:uid(),caseId:current.case.id,set:current.case.set,group:current.case.group,
    algorithmId:current.algorithm.id,algorithm:current.algorithm.alg,mode:current.mode,
    preAuf:current.preAuf,postAuf:current.postAuf,orientation:current.orientation,color:current.color,
    finish:current.finish,finishCaseId:current.finishCaseId,bottomAuf:current.bottomAuf,initialAuf:current.initialAuf,seconds:Math.max(.01,elapsed/1000),recallFail:false,dnf:false,assisted,
    createdAt:new Date().toISOString(),sessionId,inspectionSeconds,
    timingMode:activeTimingMode||selectedTimingMode(),inspectionAudio:activeInspectionAudio,
    scramble:current.scramble,solution:current.solution};
  if(data.settings.record){data.attempts.push(lastResult);persist();}shown=true;render();
}
function cancelTimer(){
  inspectionAudio.cancel();cancelAnimationFrame(raf);phase='ready';elapsed=0;
  inspectionStart=null;inspectionSeconds=null;activeTimingMode=null;activeInspectionAudio=false;
  render();toast('Timer cancelled. No result saved.');
}
function timerAction(){
  if(phase==='inspecting')startTimer();
  else if(phase==='running')finishTimer();
  else if(phase==='done')nextDrill();
  else if(selectedTimingMode()==='inspection')startInspection();
  else startTimer();
}

function reveal(){if(!current||phase==='running')return;shown=!shown;if(shown&&phase!=='done')assisted=true;render();}
async function exportBackup(){try{if(window.cornerlabNative){const result=await window.cornerlabNative.exportData(data);if(result)toast('Backup exported.');}else{download(`Corner-Lab-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2));toast('Backup downloaded.');}}catch(e){toast('Export failed: '+e.message);}}
async function importBackup(value){try{const incoming=validateData(typeof value==='string'?JSON.parse(value):value);for(const [id,p]of Object.entries(incoming.preferences)){const c=caseMap.get(id);if(!c)continue;for(const a of p.custom||[]){const valid=validateAlternative(c.algorithms[0].alg,a.alg);if(!valid.valid)throw new Error(`Invalid personal algorithm for ${id}: ${valid.reason}`);a.alg=valid.algorithm;}}const invalid=incoming.settings.selectedCases.filter(id=>!caseMap.has(id));if(invalid.length)throw new Error('This backup contains unknown case IDs.');if(!confirm(`Replace your current data with this backup?\n\nCurrent: ${data.attempts.length} 2×2 + ${data.lte.attempts.length} edges + ${data.ltc.attempts.length} centres results\nBackup: ${incoming.attempts.length} 2×2 + ${incoming.lte.attempts.length} edges + ${incoming.ltc.attempts.length} centres results\n\nAlgorithms, settings and saved practices will also be replaced. Export your current data first if needed.`))return;await saveData(incoming);data=incoming;learningSampler.reset();loadError='';storageBlocked=false;closeModal();lte.reset();ltc.reset();if(fiveTrainer())render();else nextDrill();toast('Backup restored.');}catch(e){toast('Import stopped: '+e.message);}}
async function exportCSV(){const fields=['id','createdAt','caseId','set','group','algorithmId','algorithm','seconds','recallFail','dnf','assisted','mode','preAuf','postAuf','orientation','color','finishCaseId','finish','bottomAuf','initialAuf','timingMode','inspectionAudio','inspectionSeconds','sessionId','scramble','solution'];const q=v=>`"${String(v??'').replaceAll('"','""')}"`;const content=fields.join(',')+'\n'+filteredInsights().map(a=>fields.map(k=>q(a[k])).join(',')).join('\n');try{if(window.cornerlabNative?.exportText)await window.cornerlabNative.exportText('Corner-Lab-results.csv',content,'text/csv');else download('Corner-Lab-results.csv',content,'text/csv');}catch(e){toast('Export failed: '+e.message);}}
function savePreset(){modal('Save this practice',`<label class="field"><span>Practice name</span><input class="input" id="preset-name" placeholder="e.g. EG1 Sune · recognition AUF" maxlength="80"></label><p class="help">Saves your case selection, AUFs, colors, first-layer finishes, timing, audio cues, practice focus and its clean-solve window.</p>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="save-preset">Save practice</button>`);}
function resetFiltered(){const matching=filteredInsights();if(!matching.length){toast('No matching results to reset.');return;}const filters=Object.entries(insightFilters).filter(([k,v])=>v&&v!=='all').map(([k,v])=>`${k}: ${v}`).join(' · ')||'All stored results';modal('Reset matching results',`<p>This will remove <strong>${matching.length} results</strong> from your history.</p><div class="notice">${esc(filters)}</div><p class="help">Your algorithm preferences and practice selections are kept. Export a backup first if you may want these results later.</p>`,`<button class="button" data-action="close-modal">Keep results</button><button class="button danger" data-action="confirm-reset">Delete ${matching.length} results</button>`);}

document.addEventListener('click',async event=>{
  if(!anyTimerActive()&&progress?.click(event))return;
  if(fiveTrainer())return fiveTrainer().click(event);
  if(event.target.matches('[data-case-check],[data-finish],input[type="radio"]'))return;
  const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  if(timerActive()&&!['timer','cancel-timer'].includes(a)&&!(phase==='inspecting'&&a==='reveal')){toast('Finish or cancel the current timer first.');return;}
  if(event.target.closest('a'))return;
  switch(a){
    case 'nav':page=el.dataset.page;render();break;
    case 'timer':timerAction();break;
    case 'cancel-timer':cancelTimer();break;
    case 'next':nextDrill();break;
    case 'reveal':reveal();break;
    case 'copy-scramble':try{await navigator.clipboard.writeText(current.scramble);toast('Scramble copied.');}catch{modal('Copy scramble',`<textarea readonly aria-label="Scramble to copy">${esc(current.scramble)}</textarea>`);$('.modal textarea').select();}break;
    case 'mode':data.settings.mode=el.dataset.mode;data.settings.timingMode=el.dataset.mode==='one-look'?'inspection':'simple';persist();nextDrill();break;
    case 'timing-mode':inspectionAudio.cancel();data.settings.timingMode=el.dataset.timing;persist();render();break;
    case 'toggle-set':{const ids=CASES.filter(c=>c.set===el.dataset.set).map(c=>c.id);setSelected(ids,!ids.every(id=>data.settings.selectedCases.includes(id)));updateSelection();break;}
    case 'toggle-group':{const sets=[...new Set(selectedCases().map(c=>c.set))];const ids=CASES.filter(c=>(sets.length?sets:['CLL']).includes(c.set)&&c.group===el.dataset.group).map(c=>c.id);setSelected(ids,!ids.every(id=>data.settings.selectedCases.includes(id)));updateSelection();break;}
    case 'condition':{const key=el.dataset.key,v=el.dataset.value,arr=data.settings[key];if(arr.includes(v)){if(arr.length===1){toast('Keep at least one option selected.');break;}data.settings[key]=arr.filter(x=>x!==v);}else arr.push(v);persist();render();break;}
    case 'color':{const v=el.dataset.color,arr=data.settings.colors;if(arr.includes(v)){if(arr.length===1){toast('Keep at least one first-layer color.');break;}data.settings.colors=arr.filter(x=>x!==v);}else arr.push(v);persist();render();break;}
    case 'manual':{const n=Number($('#manual-time').value);if(!Number.isFinite(n)||n<=0||n>86400){toast('Enter a time between 0.01 and 86,400 seconds.');break;}timerStart=performance.now();finishTimer(n);break;}
    case 'undo':if(lastResult){data.attempts=data.attempts.filter(a=>a.id!==lastResult.id);persist();lastResult=null;phase='ready';elapsed=0;shown=false;inspectionAudio.cancel();inspectionStart=null;inspectionSeconds=null;activeTimingMode=null;activeInspectionAudio=false;render();toast('Result discarded.');}break;
    case 'new-session':sessionId=uid();sessionStart=Date.now();render();toast('New session started. Previous results are in Insights.');break;
    case 'library-set':librarySet=el.dataset.set;render();break;
    case 'library-select':setSelected(libraryCases().map(c=>c.id),el.dataset.value==='all');render();break;
    case 'library-pattern':{const ids=libraryCases().filter(c=>c.group===el.dataset.group).map(c=>c.id);setSelected(ids,!ids.every(id=>data.settings.selectedCases.includes(id)));render();break;}
    case 'start-selection':page='train';nextDrill();break;
    case 'case-detail':showCase(el.dataset.id);break;
    case 'close-modal':closeModal();render();break;
    case 'choose-alg':chooseAlg(el.dataset.id);break;
    case 'copy-alg':{const c=caseMap.get(selectedDetail),a=algorithms(c).find(a=>a.id===el.dataset.id);if(a){$('#custom-alg').value=a.alg;$('#custom-alg').focus();}break;}
    case 'remove-alg':{const c=caseMap.get(selectedDetail),pref=data.preferences[c.id];if(pref&&confirm('Remove this personal algorithm choice? Its recorded solve history will remain.')){pref.custom=pref.custom.filter(a=>a.id!==el.dataset.id);if(pref.selected===el.dataset.id)pref.selected=c.algorithms[0].id;persist();showCase(c.id);}break;}
    case 'save-alg':{const c=caseMap.get(selectedDetail),raw=$('#custom-alg').value;if(!raw.trim()){ $('#custom-alg-error').innerHTML='<div class="error">Enter an algorithm first.</div>';break;}const result=validateAlternative(c.algorithms[0].alg,raw);if(!result.valid){$('#custom-alg-error').innerHTML=`<div class="error">${esc(result.reason)}</div>`;break;}const pref=data.preferences[c.id]||{custom:[]};pref.custom||=[];const existing=algorithms(c).find(a=>a.alg===result.algorithm);if(existing)pref.selected=existing.id;else{const id=uid();pref.custom.push({id,alg:result.algorithm,source:'Personal algorithm'});pref.selected=id;}data.preferences[c.id]=pref;persist();showCase(c.id);toast(result.correction?'Algorithm verified. Added final adjustment '+result.correction+'.':'Algorithm verified and saved.');break;}
    case 'practice-case':data.settings.selectedCases=[el.dataset.id];persist();closeModal();page='train';nextDrill();break;
    case 'finishes':showFinishes();break;
    case 'finish-select':{const ids=matchingFinishes().map(f=>f.id),set=new Set(data.settings.finishIds);ids.forEach(id=>el.dataset.value==='all'?set.add(id):set.delete(id));data.settings.finishIds=[...set];persist();$('#finish-results').innerHTML=finishResults();break;}
    case 'finish-defaults':data.settings.finishIds=[...DEFAULT_FIRST_FACE_CASE_IDS];persist();$('#finish-results').innerHTML=finishResults();break;
    case 'finish-family':{const ids=matchingFinishes().filter(f=>f.family===el.dataset.family).map(f=>f.id),set=new Set(data.settings.finishIds),all=ids.every(id=>set.has(id));ids.forEach(id=>all?set.delete(id):set.add(id));data.settings.finishIds=[...set];persist();$('#finish-results').innerHTML=finishResults();break;}
    case 'attempt':showAttempt(el.dataset.id);break;
    case 'delete-attempt':if(confirm('Delete this solve result?')){data.attempts=data.attempts.filter(a=>a.id!==el.dataset.id);persist();closeModal();render();}break;
    case 'clear-filters':insightFilters={};historyPage=0;render();break;
    case 'history-page':historyPage+=Number(el.dataset.delta);render();break;
    case 'reset-filtered':resetFiltered();break;
    case 'confirm-reset':{const ids=new Set(filteredInsights().map(a=>a.id));data.attempts=data.attempts.filter(a=>!ids.has(a.id));persist();closeModal();render();toast(`${ids.size} matching results removed.`);break;}
    case 'export':await exportBackup();break;
    case 'export-csv':await exportCSV();break;
    case 'import':try{if(window.cornerlabNative){const value=await window.cornerlabNative.importData();if(value)await importBackup(value);}else $('#import-file').click();}catch(e){toast('Import failed: '+e.message);}break;
    case 'preset':savePreset();break;
    case 'save-preset':{const name=$('#preset-name').value.trim();if(!name){toast('Give this practice a name.');break;}data.presets.push({id:uid(),name,settings:structuredClone(data.settings)});persist();closeModal();render();toast('Practice saved.');break;}
    case 'load-preset':{const p=data.presets.find(p=>p.id===el.dataset.id);if(p){data.settings={...data.settings,...structuredClone(p.settings)};learningSampler.reset();persist();page='train';nextDrill();toast(`Loaded ${p.name}.`);}break;}
    case 'delete-preset':if(confirm('Delete this saved practice? Your results will remain.')){data.presets=data.presets.filter(p=>p.id!==el.dataset.id);persist();render();}break;
  }
});
function chooseAlg(id){const c=caseMap.get(selectedDetail);if(!c)return;if(preferred(c).id!==id)resetLearning();data.preferences[c.id]={...data.preferences[c.id],selected:id};persist();showCase(c.id);toast('Preferred algorithm updated for future scrambles.');}
document.addEventListener('change',async e=>{if(e.target.id==='trainer-select'){switchTrainer(e.target.value);return;}if(!anyTimerActive()&&progress?.change(e))return;if(fiveTrainer())return fiveTrainer().change(e);const el=e.target;if(timerActive()){render();return;}if(el.dataset.caseCheck){setSelected([el.dataset.caseCheck],el.checked);render();return;}if(el.name==='preferred-alg'){chooseAlg(el.value);return;}if(el.dataset.finish){const set=new Set(data.settings.finishIds);el.checked?set.add(el.dataset.finish):set.delete(el.dataset.finish);data.settings.finishIds=[...set];persist();const summary=$('#finish-results .selection-summary');const familyButton=el.closest?.('.first-face-family')?.querySelector('[data-action=finish-family]');if(familyButton){const family=finishMap.get(el.dataset.finish).family,all=matchingFinishes().filter(f=>f.family===family).every(f=>set.has(f.id));familyButton.textContent=all?'Clear family':'Select family';familyButton.setAttribute('aria-label',`${all?'Clear':'Select'} ${FIRST_FACE_FAMILIES.find(f=>f.id===family).name} family`);}if(summary)summary.textContent=`${set.size.toLocaleString()} selected · ${matchingFinishes().length.toLocaleString()} match${matchingFinishes().length===1?'':'es'}`;return;}if(el.dataset.resultFlag&&lastResult){lastResult[el.dataset.resultFlag]=el.checked;persist();render();return;}if(el.dataset.attemptFlag){const a=data.attempts.find(a=>a.id===el.dataset.id);if(a){a[el.dataset.attemptFlag]=el.checked;persist();}return;}if(el.dataset.insightFilter){insightFilters[el.dataset.insightFilter]=el.value;if(el.dataset.insightFilter==='set')delete insightFilters.caseId;historyPage=0;render();return;}switch(el.id){case 'inspection-audio':data.settings.inspectionAudio=el.checked;persist();render();break;case 'insight-selection':insightFilters.selectionOnly=el.checked;historyPage=0;render();break;case 'focus-select':if(data.settings.strategy!==el.value)resetLearning();data.settings.strategy=el.value;persist();render();break;case 'speed-window':{const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>MAX_SPEED_WINDOW){toast(`Enter a whole number from 1 to ${MAX_SPEED_WINDOW.toLocaleString()}.`);render();break;}data.settings.slowWindow=n;persist();render();break;}case 'rank-count':{const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>MAX_RANK_COUNT){toast(`Enter a whole number from 1 to ${MAX_RANK_COUNT.toLocaleString()}.`);render();break;}data.settings.rankCount=n;persist();render();break;}case 'insights-window':{const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>MAX_INSIGHTS_WINDOW){toast(`Enter a whole number from 1 to ${MAX_INSIGHTS_WINDOW.toLocaleString()}.`);render();break;}data.settings.insightsWindow=n;persist();render();break;}case 'library-group':libraryGroup=el.value;render();break;case 'finish-group':finishGroup=el.value;$('#finish-results').innerHTML=finishResults();break;case 'finish-length':finishLength=el.value;$('#finish-results').innerHTML=finishResults();break;case 'insight-group':insightGroup=el.value;render();break;case 'insight-sort':insightSort=el.value;render();break;case 'record-toggle':data.settings.record=el.checked;persist();render();break;case 'preview-toggle':data.settings.showPreview=el.checked;persist();render();break;case 'import-file':if(el.files[0])await importBackup(await el.files[0].text());break;}});
document.addEventListener('input',e=>{if(!anyTimerActive()&&progress?.input(e))return;if(fiveTrainer())return fiveTrainer().input(e);if(e.target.id==='library-search'){libraryQuery=e.target.value;$('#library-results').innerHTML=libraryResults();}if(e.target.id==='finish-search'){finishQuery=e.target.value;$('#finish-results').innerHTML=finishResults();}});
document.addEventListener('keydown',e=>{
  if(fiveTrainer())return fiveTrainer().keydown(e,page);
  if(e.key==='Escape'){
    if($('.modal')){closeModal();render();return;}
    if(timerActive()){e.preventDefault();cancelTimer();return;}
  }
  if($('.modal')){
    if(e.key==='Tab'){
      const elements=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);
      const first=elements[0],last=elements.at(-1);
      if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
      else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
    }
    return;
  }
  if(e.target.matches('input,textarea,select')||e.target.isContentEditable||e.metaKey||e.ctrlKey||e.altKey)return;
  if(e.key==='Enter'&&e.target.matches('.case-card')){showCase(e.target.dataset.id);return;}
  if(page!=='train')return;
  if(e.code==='Space'){
    e.preventDefault();
    if(e.repeat||spaceHeld)return;
    spaceHeld=true;timerAction();
  }else if(!e.repeat&&e.key.toLowerCase()==='n'&&!timerActive())nextDrill();
  else if(!e.repeat&&e.key.toLowerCase()==='h')reveal();
});
// Prevent a held key or its release from advancing more than one stage.
document.addEventListener('keyup',e=>{
  if(fiveTrainer())return fiveTrainer().keyup(e);
  if(e.code==='Space'&&spaceHeld){e.preventDefault();spaceHeld=false;}
});
window.addEventListener('blur',()=>{spaceHeld=false;lte?.blur();ltc?.blur();});
function interruptTiming(){
  spaceHeld=false;inspectionAudio.cancel();
  if(timerActive())cancelTimer();
  lte?.interrupt();ltc?.interrupt();
  syncTimerState();
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')interruptTiming();else syncTimerState();});
window.addEventListener('pagehide',interruptTiming);


try{data=await loadData();}catch(e){data=freshData();storageBlocked=true;loadError=`Saved data could not be loaded: ${e.message}. The saved file has been left untouched. Import a valid backup to restore recording.`;}
if(!data.initialized){data.settings.selectedCases=CASES.filter(c=>c.set==='CLL'&&c.group==='Sune').map(c=>c.id);data.initialized=true;if(!storageBlocked)persist();}
progress=createProgressView({getData:()=>data,render,casesCentres:CASES_CENTRES});
const trainerDependencies={getData:()=>data,persist,render,toast,navigate:nextPage=>{page=nextPage;render();},modal,closeModal,exportBackup,importBackup,download,canSave:()=>!storageBlocked,document,window,now:()=>performance.now(),requestFrame:fn=>requestAnimationFrame(fn),cancelFrame:id=>cancelAnimationFrame(id),createAudio:createInspectionAudio};
lte=createLTETrainer({...trainerDependencies,progressHTML:()=>progress.content({trainer:'5x5'})});
ltc=createLTETrainer({...trainerDependencies,kind:'centres',catalog:CASES_CENTRES,storageKey:'ltc',setId:'L2C',diagram:centreSVG5,buildDrill:createCentresDrill,progressHTML:()=>progress.content({trainer:'5x5-centres'})});
if(fiveTrainer())fiveTrainer().next();else nextDrill();

function switchTrainer(trainer){
  if(!['2x2','5x5','5x5-centres'].includes(trainer)||trainer===data.trainer)return;
  if(anyTimerActive()){toast('Finish or cancel the current timer first.');render();return;}
  inspectionAudio.cancel();lte.leave();ltc.leave();spaceHeld=false;closeModal();data.trainer=trainer;page='train';persist();
  if(fiveTrainer())fiveTrainer().next();else nextDrill();
}

